select count(1)
from clubs

  
    (club_name like concat('%', #{keyword}, '%')
    or club_code like concat('%', #{keyword}, '%'))
  
  
    and status = #{status}
  
  
    and founder_id = #{founderId}
  
  
    and member_count >= #{minMemberCount}
  
  
    and member_count <= #{maxMemberCount}

select

from clubs

  
    (club_name like concat('%', #{keyword}, '%')
    or club_code like concat('%', #{keyword}, '%'))
  
  
    and status = #{status}
  
  
    and founder_id = #{founderId}
  
  
    and member_count >= #{minMemberCount}
  
  
    and member_count <= #{maxMemberCount}
  

order by

  
    ${sortField}
  
  
    created_time
  


  
    asc
  
  
    desc
  

limit #{size} offset #{offset}

